package com.neueda.leap.repository;

import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Update;

import java.time.LocalDate;

// The statements that open a trading account for a user who has only registered a login.
// External ids are generated by Postgres; INSERT ... RETURNING runs as a @Select so it can return the new id.
@Mapper
public interface AccountOpeningMapper {

    @Select("INSERT INTO clients (external_client_id, first_name, last_name, email, birth_date) "
            + "VALUES (gen_random_uuid(), #{firstName}, #{lastName}, #{email}, #{birthDate}) "
            + "RETURNING client_id")
    @Options(flushCache = Options.FlushCachePolicy.TRUE)
    Long insertClient(@Param("firstName") String firstName, @Param("lastName") String lastName,
                      @Param("email") String email, @Param("birthDate") LocalDate birthDate);

    // a new account starts with no cash; the user deposits funds into it
    @Select("INSERT INTO accounts (external_account_id, balance) VALUES (gen_random_uuid(), 0) RETURNING account_id")
    @Options(flushCache = Options.FlushCachePolicy.TRUE)
    Long insertAccount();

    @Insert("INSERT INTO client_accounts (client_id, account_id) VALUES (#{clientId}, #{accountId})")
    void linkClientToAccount(@Param("clientId") Long clientId, @Param("accountId") Long accountId);

    // only links a user who has no client yet; returns 0 if the user already has one (or doesn't exist)
    @Update("UPDATE users SET client_id = #{clientId} WHERE user_id = #{userId} AND client_id IS NULL")
    int linkUserToClient(@Param("userId") Long userId, @Param("clientId") Long clientId);
}
